// ─── Per-page SEO metadata ────────────────────────────────────────────────────
// One helper so every page gets the same set: description, canonical, Open
// Graph and Twitter card. It never sets `title`: the browser tab reads
// "Alvea Viagens" on every page (see src/app/layout.tsx). `shareTitle` is only
// the headline shown when the link is shared.

import type { Metadata } from 'next'
import { SITE_NAME } from '@/lib/config/site'

/* Link preview image (1200×630), generated by scripts/build-brand-images.mjs */
const SHARE_IMAGE = { url: '/og-image.png', width: 1200, height: 630, alt: 'Alvea Viagens — Agência de viagens' }

interface PageSeo {
  path:        string
  shareTitle:  string
  description: string
  /* false keeps the page out of search results (it stays reachable by URL) */
  index?:      boolean
}

export function pageMetadata({ path, shareTitle, description, index = true }: PageSeo): Metadata {
  return {
    description,
    alternates: { canonical: path },
    ...(index ? {} : { robots: { index: false, follow: true } }),
    openGraph: {
      title: shareTitle,
      description,
      url: path,
      siteName: SITE_NAME,
      type: 'website',
      locale: 'pt_BR',
      images: [SHARE_IMAGE],
    },
    twitter: {
      card: 'summary_large_image',
      title: shareTitle,
      description,
      images: [SHARE_IMAGE.url],
    },
  }
}
